head.script:
window.dataLayer = window.dataLayer || [];
function gtag() { dataLayer.push(arguments); }

var consentAdUserData = null;
var consentAdPersonalization = null;
var consentAdStorage = null;
var consentAnalyticsStorage = null;
try {
  consentAdUserData = localStorage.getItem("consentAdUserData");
  consentAdPersonalization = localStorage.getItem("consentAdPersonalization");
  consentAdStorage = localStorage.getItem("consentAdStorage");
  consentAnalyticsStorage = localStorage.getItem("consentAnalyticsStorage");
} catch (e) {
  // localStorage can throw (e.g. Safari "Block All Cookies"); default to denied below.
}

gtag('consent', 'default', {
  ad_user_data: consentAdUserData === "true" ? "granted" : "denied",
  ad_personalization: consentAdPersonalization === "true" ? "granted" : "denied",
  ad_storage: consentAdStorage === "true" ? "granted" : "denied",
  analytics_storage: consentAnalyticsStorage === "true" ? "granted" : "denied",
  wait_for_update: 500,
})
gtag("js", new Date())

var gtmScript = document.createElement('script');
gtmScript.async = true;
gtmScript.src = 'https://www.googletagmanager.com/gtm.js?id=GTM-MCGV7CTR';

var firstScript = document.getElementsByTagName('script')[0];
firstScript.parentNode.insertBefore(gtmScript,firstScript);

// Load gtag library once (with the first available ID)
var gtagScript = document.createElement('script');
gtagScript.async = true;
gtagScript.src = 'https://www.googletagmanager.com/gtag/js?id=G-BVW833LF8Q';

var firstScript = document.getElementsByTagName('script')[0];
firstScript.parentNode.insertBefore(gtagScript, firstScript);

// Configure Google Analytics
gtag("config", "G-BVW833LF8Q", { send_page_view: false });

